#!/usr/bin/env python3
"""
Round 136b (culprits-tiles-more), 2 October 2026.

ocean_stressors.py (new): six pressures of Halpern et al. 2019 as rows of their own.
offshore_platforms.py (new): every offshore platform OpenStreetMap maps.

Writes each file only if it differs. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/ocean_stressors.py': '', 'scripts/offshore_platforms.py': ''}


def main():
    for path, b64 in FILES.items():
        p = pathlib.Path(path)
        data = base64.b64decode(b64)
        if p.exists() and p.read_bytes() == data:
            print(f"round136b_tiles: {path} already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        print(f"round136b_tiles: wrote {path}")


if __name__ == "__main__":
    main()
